<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Windows technical documentation for developers and IT pros</title>
<script src="https://polyfill.io/v3/polyfill.min.js?features=es6"></script>
<script id="MathJax-script" async src="https://cdn.jsdelivr.net/npm/mathjax@3/es5/tex-mml-chtml.js"></script>
<style>
  * { box-sizing: border-box; }
  body {
    margin: 0;
    font-family: -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    color: #1b1b1b;
  }

  /* Top promo bar */
  .promo-bar {
    background: #000;
    color: #fff;
    position: relative;
    padding: 20px 40px;
    height: 130px;
    overflow: hidden;
  }
  .promo-title {
    font-size: 28px;
    font-weight: 600;
    margin: 0 0 8px 0;
  }
  .promo-date {
    font-size: 13px;
    color: #ccc;
    margin-bottom: 14px;
  }
  .learn-more-btn {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    background: #fff;
    color: #000;
    border: none;
    border-radius: 4px;
    padding: 10px 18px;
    font-size: 13px;
    font-weight: 600;
  }
  .promo-close {
    position: absolute;
    top: 14px;
    right: 20px;
    width: 28px;
    height: 28px;
    background: #fff;
    color: #000;
    border-radius: 3px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 14px;
    font-weight: bold;
  }
  .promo-graphic {
    position: absolute;
    right: 0;
    bottom: 0;
    width: 350px;
    height: 100px;
    background: linear-gradient(120deg, #f5a623 0%, #e8348c 15%, #6a3bd6 30%, #2ea8e8 45%, #29c98f 60%, #7ed321 75%, #c9e83b 90%);
    clip-path: polygon(0% 100%, 10% 60%, 20% 100%, 30% 40%, 40% 100%, 50% 70%, 60% 100%, 70% 30%, 80% 100%, 90% 55%, 100% 100%, 100% 0%, 0% 0%);
    opacity: 0.9;
  }

  /* Learn navbar */
  .learn-nav {
    display: flex;
    align-items: center;
    padding: 14px 40px;
    border-bottom: 1px solid #e1e1e1;
    background: #fff;
  }
  .ms-logo {
    width: 22px;
    height: 22px;
    background: conic-gradient(#f25022 0turn 0.25turn, #7fba00 0.25turn 0.5turn, #00a4ef 0.5turn 0.75turn, #ffb900 0.75turn 1turn);
    margin-right: 14px;
  }
  .learn-label {
    font-size: 17px;
    font-weight: 600;
    margin-right: 16px;
  }
  .divider {
    color: #ccc;
    margin-right: 16px;
  }
  .learn-nav-links {
    display: flex;
    gap: 26px;
    flex: 1;
    font-size: 14px;
    color: #333;
  }
  .learn-nav-links span {
    cursor: pointer;
  }
  .learn-nav-right {
    display: flex;
    align-items: center;
    gap: 24px;
    font-size: 14px;
  }
  .signin-link {
    color: #0067c0;
  }

  /* Windows sub navbar */
  .windows-nav {
    display: flex;
    align-items: center;
    padding: 14px 40px;
    background: #faf9f8;
    border-bottom: 1px solid #e1e1e1;
    font-size: 14px;
    gap: 26px;
  }
  .windows-nav .title {
    font-size: 20px;
    font-weight: 700;
    margin-right: 20px;
  }

  /* Hero section */
  .hero {
    background: #0067c0;
    background-image:
      repeating-linear-gradient(0deg, transparent, transparent 39px, rgba(255,255,255,0.15) 39px, rgba(255,255,255,0.15) 40px),
      repeating-linear-gradient(90deg, transparent, transparent 39px, rgba(255,255,255,0.15) 39px, rgba(255,255,255,0.15) 40px);
    color: #fff;
    padding: 50px 40px 60px 40px;
  }
  .hero h1 {
    font-size: 42px;
    font-weight: 600;
    margin: 0 0 20px 0;
    max-width: 750px;
    line-height: 1.2;
  }
  .hero p {
    font-size: 16px;
    margin: 0;
    max-width: 700px;
  }

  /* Cards grid */
  .cards-wrapper {
    padding: 40px;
  }
  .cards-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 20px;
  }
  .card {
    border: 1px solid #e1e1e1;
    border-radius: 4px;
    padding: 24px;
  }
  .card .icon {
    width: 36px;
    height: 36px;
    margin-bottom: 12px;
    border: 2px solid #0067c0;
    border-radius: 4px;
    color: #0067c0;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 18px;
  }
  .card h3 {
    font-size: 16px;
    color: #0067c0;
    margin: 0 0 10px 0;
    font-weight: 600;
  }
  .card p {
    font-size: 13px;
    line-height: 1.5;
    color: #444;
    margin: 0;
  }

  /* Footer */
  .footer {
    background: #eeece9;
    padding: 30px 40px;
    font-size: 13px;
    color: #333;
    margin-top: 60px;
  }
  .footer-top {
    display: flex;
    gap: 30px;
    margin-bottom: 20px;
    align-items: center;
  }
  .footer-bottom {
    display: flex;
    gap: 26px;
    flex-wrap: wrap;
    border-top: none;
  }
  .footer-bottom a {
    color: #333;
    text-decoration: none;
  }
</style>
</head>
