    <div class="promo-date">June 2-3, 2026</div>
    <button class="learn-more-btn">Learn more &gt;</button>
    <div class="promo-graphic"></div>
    <div class="promo-close">&#10005;</div>
  </div>

  <!-- Learn navbar -->
  <div class="learn-nav">
    <div class="ms-logo"></div>
    <div class="learn-label">Learn</div>
    <div class="learn-nav-links">
      <span>Documentation &#8964;</span>
      <span>Training &amp; Labs &#8964;</span>
      <span>Q&amp;A &#8964;</span>
      <span>Topics &#8964;</span>
    </div>
    <div class="learn-nav-right">
      <span>&#128269;</span>
      <span class="signin-link">Sign in</span>
    </div>
  </div>

  <!-- Windows sub navbar -->
  <div class="windows-nav">
    <span class="title">Windows</span>
    <span>Release health</span>
    <span>Windows client &#8964;</span>
